def match_route(pattern, path):
    pattern_parts = [p for p in str(pattern).strip('/').split('/') if p]
    path_parts = [p for p in str(path).strip('/').split('/') if p]
    if len(pattern_parts) != len(path_parts):
        return None
    params = {}
    for template, actual in zip(pattern_parts, path_parts):
        if template.startswith('<') and template.endswith('>'):
            params[template[1:-1]] = actual
        elif template != actual:
            return None
    return params


def parse_pagination(query):
    errors = []
    page, size = 1, 10
    raw_page = (query or {}).get('page')
    raw_size = (query or {}).get('size')
    if raw_page is not None:
        try:
            page = int(raw_page)
            if page < 1:
                raise ValueError
        except (TypeError, ValueError):
            errors.append('page 必须是正整数')
            page = 1
    if raw_size is not None:
        try:
            size = int(raw_size)
            if size < 1:
                raise ValueError
            if size > 100:
                errors.append('size 不能超过 100')
                size = 10
        except (TypeError, ValueError):
            errors.append('size 必须是正整数')
            size = 10
    return page, size, errors


print(match_route('/users/<id>/posts', '/users/42/posts'))
print(match_route('/users/<id>/posts', '/users/42/comments'))
print(parse_pagination({'page': '3', 'size': '20'}))
print(parse_pagination({'page': '0', 'size': 'abc'}))
print(parse_pagination({'size': '500'}))
